from __future__ import annotations

import os
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone
from html import escape as xml_escape
from collections import defaultdict, deque

from flask import Flask, Response, abort, jsonify, redirect, render_template, request, send_file

from . import cms
from . import currency_rates


ORDER_RATE = defaultdict(deque)


class _NoRedirectHandler(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


_NO_REDIRECT_OPENER = urllib.request.build_opener(_NoRedirectHandler)

def create_app() -> Flask:
    root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    app = Flask(__name__, template_folder=os.path.join(root, "templates"),
                static_folder=os.path.join(root, "static"))

    @app.after_request
    def security_headers(response):
        response.headers.setdefault("X-Frame-Options", "SAMEORIGIN")
        response.headers.setdefault("X-Content-Type-Options", "nosniff")
        response.headers.setdefault("Referrer-Policy", "strict-origin-when-cross-origin")
        response.headers.setdefault("Permissions-Policy", "geolocation=(), microphone=(), camera=()")
        response.headers.setdefault("Content-Security-Policy", "default-src 'self'; img-src 'self' data:; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline' https://cdnjs.cloudflare.com https://static.cloudflareinsights.com; connect-src 'self'; frame-ancestors 'self'")
        if request.path.startswith("/static/"):
            response.headers.setdefault("Cache-Control", "public, max-age=2592000, immutable")
        elif request.path in {"/robots.txt", "/sitemap.xml", "/image-sitemap.xml"}:
            response.headers.setdefault("Cache-Control", "public, max-age=3600")
        else:
            response.headers.setdefault("Cache-Control", "public, max-age=300")
        return response

    @app.get("/")
    def home():
        tenant = request_tenant()
        lang = request.args.get("lang") or cms.DEFAULT_LANG
        theme = request.args.get("theme")
        rt = cms.runtime(tenant, lang, "home", theme)
        seo = cms.seo_context(rt, public_base_url(), "home")
        return render_template("themes/generic/index.html", rt=rt, seo=seo, initial_panel="", L=cms.localized, T=cms.tr)

    @app.get("/cart")
    @app.get("/checkout")
    @app.get("/account")
    @app.get("/returns")
    def commerce_page():
        tenant = request_tenant()
        lang = request.args.get("lang") or cms.DEFAULT_LANG
        theme = request.args.get("theme")
        rt = cms.runtime(tenant, lang, "home", theme)
        seo = cms.seo_context(rt, public_base_url(), "home")
        languages = list(rt.config.get("languages") or [rt.lang])
        seo["canonical_url"] = cms.page_url(public_base_url(), request.path, rt.lang)
        seo["alternates"] = [
            {"lang": item, "hreflang": item, "url": cms.page_url(public_base_url(), request.path, item)}
            for item in languages
        ]
        seo["alternates"].append({
            "lang": "x-default",
            "hreflang": "x-default",
            "url": cms.page_url(public_base_url(), request.path, rt.config.get("default_language", cms.DEFAULT_LANG)),
        })
        panel_map = {
            "/cart": "cart",
            "/checkout": "cart",
            "/account": "account",
            "/returns": "account",
        }
        section_map = {
            "/returns": "returns",
            "/account": "settings",
        }
        return render_template(
            "themes/generic/index.html",
            rt=rt,
            seo=seo,
            initial_panel=panel_map.get(request.path, ""),
            initial_account_section=section_map.get(request.path, ""),
            L=cms.localized,
            T=cms.tr,
        )

    @app.get("/p/<slug>")
    def product(slug: str):
        tenant = request_tenant()
        lang = request.args.get("lang") or cms.DEFAULT_LANG
        theme = request.args.get("theme")
        rt = cms.runtime(tenant, lang, "home", theme, include_products=False, include_facets=False)
        raw_item = cms.find_product_by_slug(tenant, slug, rt.lang)
        if not raw_item:
            abort(404)
        item = cms.localize_product(raw_item, rt.lang, rt.tenant)
        seo = cms.seo_context(rt, public_base_url(), "product", product=item, raw_product=raw_item)
        source_payload = cms.seo_engine.product_source_payload(item, rt.lang)
        return render_template(
            "themes/generic/product.html",
            rt=rt,
            product=item,
            related_products=cms.related_products(tenant, raw_item, rt.lang),
            review_summary=cms.review_summary(item),
            seo=seo,
            source_payload=source_payload,
            L=cms.localized,
            T=cms.tr,
        )

    @app.get("/legal/<slug>")
    def legal(slug: str):
        tenant = request_tenant()
            sort=request.args.get("sort") or "relevance",
            filters={
                "min_price": request.args.get("min_price"),
                "max_price": request.args.get("max_price"),
                "in_stock": request.args.get("in_stock"),
                "material": request.args.get("material"),
                "color": request.args.get("color"),
                "finish": request.args.get("finish"),
                "capacity": request.args.get("capacity"),
            },
        )
        return jsonify(result)

    @app.post("/api/orders")
    def api_orders():
        tenant = request_tenant()
        ip = request.headers.get("CF-Connecting-IP") or request.headers.get("X-Forwarded-For", "").split(",")[0] or request.remote_addr or "unknown"
        now = time.time()
        bucket = ORDER_RATE[ip]
        while bucket and now - bucket[0] > 600:
            bucket.popleft()
        if len(bucket) >= 5:
            return jsonify({"status": "error", "error": "rate_limited"}), 429
        payload = request.get_json(force=True)
        customer_payload = payload.get("customer") or {}
        if payload.get("website") or customer_payload.get("website"):
            return jsonify({"status": "error", "error": "spam_detected"}), 400
        try:
            result = cms.save_order(tenant, payload)
        except ValueError as exc:
            return jsonify({"status": "error", "error": str(exc)}), 400
        bucket.append(now)
        return jsonify(result)

    @app.post("/api/account/login")
    def api_account_login():
        tenant = request_tenant()
        try:
            result = cms.login_customer_account(tenant, request.get_json(force=True))
        except ValueError as exc:
            return jsonify({"status": "error", "error": str(exc)}), 400
        return jsonify(result)

    @app.post("/api/account/change-password")
    def api_account_change_password():
        tenant = request_tenant()
        try:
            result = cms.change_customer_password(tenant, request.get_json(force=True))
        except ValueError as exc:
            return jsonify({"status": "error", "error": str(exc)}), 400
        return jsonify(result)

    @app.post("/api/account/orders")
    def api_account_orders():
        tenant = request_tenant()
        try:
            result = cms.list_customer_orders(tenant, request.get_json(force=True))
        except ValueError as exc:
            return jsonify({"status": "error", "error": str(exc)}), 403
        return jsonify(result)

    @app.post("/api/account/returns")
    def api_account_returns():
        tenant = request_tenant()
        try:
            result = cms.create_customer_return(tenant, request.get_json(force=True))
        except ValueError as exc:
            return jsonify({"status": "error", "error": str(exc)}), 400
        return jsonify(result)

    @app.get("/admin/api/themes")
    def api_themes():
        return jsonify(cms.theme_registry())

    @app.get("/admin/api/tenants/<tenant>/validate")
    def api_validate(tenant: str):
        return jsonify(cms.validate_tenant(tenant))

    @app.post("/admin/api/tenants/<tenant>/import/json")
    def api_import_json(tenant: str):
        return jsonify(cms.import_catalog_payload(tenant, request.get_json(force=True), "json"))

    @app.get("/health")
    def health():
        return {"status": "ok"}

    return app


def tenant_from_host() -> str:
    host = (request.headers.get("X-Forwarded-Host") or request.host or "").split(":")[0]
    label = host.split(".")[0] if host else ""
    if label in ("", "localhost", "127", "www"):
        return os.environ.get("EVA_DEFAULT_STOREFRONT_TENANT", "cesiro1")
    return label


def request_tenant() -> str:
    host = (request.headers.get("X-Forwarded-Host") or request.host or "").split(":")[0].lower()
    label = host.split(".")[0] if host else ""
    is_local = (
        label in ("", "localhost", "127", "0")
        or host.startswith("127.")
        or host.startswith("localhost")
        or host in ("0.0.0.0", "::1")
    )
    if is_local:
        return request.args.get("tenant") or tenant_from_host()
    return tenant_from_host()

