BNR_URL = "https://curs.bnr.ro/nbrfxrates.xml"
EVA_API_URL = os.environ.get("EVA_API_URL", "http://localhost:8000/api/v1")
COUNTRY_CURRENCY = {"RO": "RON", "HU": "HUF", "BG": "BGN", "GR": "EUR"}
SHOWN = ["RON", "HUF", "BGN", "EUR"]
FALLBACK_RATES = {"RON": 1.0, "HUF": 0.0129, "BGN": 2.594, "EUR": 5.07}


def curs_fix_bgn_eur(la: str) -> float:
    """T159 E: cursul fix BGN / EUR (Consiliul UE) din registrul legislativ al EvA la data cursului BNR `la` (AAAA-LL-ZZ) —
    GET {EVA_API_URL}/registru-legal/CURS_FIX_BGN_EUR?la= (doar citire, backend-ul EvA, nu un partener); rândul lipsă /
    backend indisponibil = excepție (niciun curs presupus în cod)."""
    req = urllib.request.Request(f"{EVA_API_URL}/registru-legal/CURS_FIX_BGN_EUR?la={la}")
    tok = os.environ.get("EVA_COMMERCE_SERVICE_TOKEN", "").strip()
    if tok:
        req.add_header("Authorization", f"Bearer {tok}")
    with urllib.request.urlopen(req, timeout=10) as r:
        return float(json.load(r)["valoare"])


def _parse_bnr_xml(xml: str) -> dict[str, Any]:
    match = re.search(r'<Cube date="([^"]+)"', xml)
    date = match.group(1) if match else datetime.now(timezone.utc).date().isoformat()
    rates = {"RON": 1.0}
    for item in re.finditer(r'<Rate currency="([A-Z]{3})"(?:\s+multiplier="(\d+)")?>([\d.]+)</Rate>', xml):
        code, multiplier, value = item.group(1), item.group(2), item.group(3)
        rates[code] = float(value) / (float(multiplier) if multiplier else 1.0)
    if "BGN" not in rates and "EUR" in rates:
        rates["BGN"] = rates["EUR"] / curs_fix_bgn_eur(date)   # T159 E
    return {"base": "RON", "date": date, "rates": rates, "shown": SHOWN, "country_currency": COUNTRY_CURRENCY, "source": "bnr"}


def fetch_bnr() -> dict[str, Any]:
    with urllib.request.urlopen(BNR_URL, timeout=20) as response:
        data = _parse_bnr_xml(response.read().decode("utf-8"))
    os.makedirs(os.path.dirname(CACHE), exist_ok=True)
    data["synced_at"] = datetime.now(timezone.utc).isoformat()
    with open(CACHE, "w", encoding="utf-8") as fh:
        json.dump(data, fh, ensure_ascii=False, indent=2)
        fh.write("\n")
    return data


def _normalize_cached(data: dict[str, Any]) -> dict[str, Any]:
    data.setdefault("country_currency", COUNTRY_CURRENCY)
    data.setdefault("shown", SHOWN)
    rates = data.setdefault("rates", {})
    if "BGN" not in rates and "EUR" in rates:
        rates["BGN"] = float(rates["EUR"]) / curs_fix_bgn_eur(data.get("date") or "")   # T159 E
    return data


def _is_current_bnr_day(data: dict[str, Any]) -> bool:
    return data.get("source") == "bnr" and data.get("date") == datetime.now(timezone.utc).date().isoformat()


def get_rates(refresh: bool = False) -> dict[str, Any]:
    cached: dict[str, Any] | None = None
    if os.path.exists(CACHE):
        try:
            with open(CACHE, encoding="utf-8") as fh:
                cached = _normalize_cached(json.load(fh))
            if not refresh and _is_current_bnr_day(cached):
                return cached
        except Exception:
            cached = None
    try:
        return fetch_bnr()
    except Exception as exc:
        if cached:
            cached["stale"] = True
            cached["refresh_error"] = str(exc)[:200]
            return cached
        return {"base": "RON", "date": "fallback", "rates": FALLBACK_RATES, "shown": SHOWN, "country_currency": COUNTRY_CURRENCY, "source": "fallback", "error": str(exc)[:200]}


def currency_for_country(country: str | None) -> str:
    return COUNTRY_CURRENCY.get(str(country or "RO").upper(), "RON")


def convert_from_ron(amount_ron: float | int | str | None, currency: str, rates: dict[str, Any] | None = None) -> float:
    rates = rates or get_rates()
    code = (currency or "RON").upper()
    amount = Decimal(str(amount_ron or 0))
    rate = Decimal(str((rates.get("rates") or {}).get(code) or 1))
    if code == "RON" or rate == 0:
        return float(amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))
    return float((amount / rate).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))


