def login_customer_account(tenant: str, payload: dict[str, Any]) -> dict[str, Any]:
    tenant = safe_id(tenant)
    email = str(payload.get("email") or "").strip().lower()
    password = str(payload.get("password") or "")
    if not email or not password:
        raise ValueError("missing_login")
    data = read_json(account_path(tenant, email), {})
    if not data or data.get("status") != "active" or not verify_password(password, data.get("password_hash", "")):
        raise ValueError("invalid_login")
    if not data.get("customer_token"):
        data["customer_token"] = secrets.token_urlsafe(24)
        data["updated_at"] = datetime.now(timezone.utc).isoformat()
        write_json(account_path(tenant, email), data)
    return {
        "status": "ok",
        "account_id": data.get("id"),
        "email": data.get("email"),
        "name": data.get("name"),
        "customer_token": data.get("customer_token"),
        "account_type": "store_customer",
        "must_change_password": bool(data.get("must_change_password")),
        "shipping_addresses": data.get("shipping_addresses", []),
        "active_shipping_address_id": data.get("active_shipping_address_id", ""),
    }
